import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3, Euler } = ctx.THREE;

  // Root group
  const root = new Group();
  root.position.copy(new Vector3(...(config.scenePosition || [0, -2.85, 0.26])));
  if (config.sceneRotation) {
    root.rotation.copy(new Euler(...config.sceneRotation));
  }
  if (config.sceneScale) {
    root.scale.copy(new Vector3(...config.sceneScale));
  }

  // Geometry: plane sized to fit 512x320 atlas region (aspect 1.6)
  // At default 1 unit = ~100px scene scale, this is ~5.12 x 3.2 units
  // For a button-scale CTA, constrain to ~1.2 x 0.75 units
  const geometry = new PlaneGeometry(1.2, 0.75);

  // Load the brushed-metal texture
  const brushedMetalPromise = ctx.textureLoader.loadTexture(config.imageUrl);

  // Create text label
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = textItems.find(item => item.role === 'headline') || { text: 'Get started', typography: { fontSize: 42 } };
  const headline = ctx.fontAtlas.createText(headlineItem.text, {
    fontSize: headlineItem.typography?.fontSize || 42,
    color: config.intent?.visualSpec?.colors?.paper || '#e8ecf2',
    align: 'center'
  });
  headline.position.z = 0.05;
  root.add(headline);

  // Create the plane with material
  let meshMaterial;
  let textureMesh;

  brushedMetalPromise.then((texture) => {
    // TSL-based material with subtle engineered gradient overlay
    const uvNode = uv();

    // Gradient: vertical, darker at bottom (surface color) to lighter paper at top
    const gradientY = uvNode.y;
    const surfaceColor = color(config.intent?.visualSpec?.colors?.surface || '#0b0b10');
    const paperColor = color(config.intent?.visualSpec?.colors?.paper || '#e8ecf2');
    const gradientMix = mix(surfaceColor, paperColor, mix(0.2, 0.4, gradientY));

    // Subtle grain overlay (procedural noise via fract sin)
    const noiseUv = uvNode.mul(vec3(12, 8, 1));
    const grain = mix(0.92, 1.0, noiseUv.x.fract().mul(0.1).add(noiseUv.y.fract().mul(0.05)));

    meshMaterial = new MeshBasicNodeMaterial({
      colorNode: gradientMix.mul(grain),
      map: texture,
      toneMapped: true
    });

    textureMesh = new Mesh(geometry, meshMaterial);
    root.add(textureMesh);
  });

  // Cleanup function
  root.userData.cleanup = () => {
    geometry.dispose();
    if (meshMaterial) meshMaterial.dispose();
    if (textureMesh) textureMesh.geometry.dispose();
    // Kill any GSAP timelines
    gsap.killTweensOf(root);
    gsap.killTweensOf(headline);
  };

  root.userData.handlers = {};

  return root;
}
